(* [comment removed for export] *)
Lemma accessible_vt16 {HCEIL : HeapCeil} : forall m, ACONST m ->
  accessible m (AVP_SSVC + 16) 8 /\ accessible m (AVP_SCHED + 16) 8 /\ accessible m (AVP_CONFIG_SVC + 16) 8.
Proof. intros m AC. split; [| split]; apply (ACONST_img_accessible m _ _ AC); vm_compute; reflexivity. Qed.

