  (* [comment removed for export] *)
  Lemma frobj_block_off : forall s LB m0 LF m1 A n p X k, as_RHEAP H s LB m0 -> as_RFS H LF m1 -> frobj LF A n -> In (p, X, k) LB ->
    A + n <= X \/ X + k <= A.
  Proof.
    intros s LB m0 LF m1 A n p X k RH RF FO IN.
    pose proof (frobj_range _ _ _ _ RF FO) as (B1 & B2 & _).
    pose proof (ah_blocks H HH _ _ _ _ RH IN) as (_ & _ & K3 & _ & _ & K6 & _). cbn [blk_addr blk_size fst snd] in K3, K6.
    unfold AFS_HDR in *. lia.
  Qed.
