  Lemma ARegistry_glue : forall s LB m r owner first lk, as_RHEAP H s LB m -> ARegistry LB m r owner first lk ->
    rw_cells bsegs m (r + O_REG_OWNER) [C8 (wz owner); C8 (wz first)] /\ addressable m r NEWSZ_REG /\ 0 < r /\ r + NEWSZ_REG <= aceil
    /\ r mod 16 = 0 /\ aapp r NEWSZ_REG /\ (exists p, In (p, r, NEWSZ_REG) LB).
  Proof.
    intros s LB m r owner first lk RH (p & j0 & j7 & IN & C0 & PM & C1 & C2 & RB & AD).
    pose proof RB as (R1 & R2 & _ & R4 & R5). split; [exact C1|]. split; [exact AD|]. repeat (split; [assumption|]). exists p. exact IN.
  Qed.

