Definition ectx_shW (lo : Z) (sp : word) (q schedb ff1 fp1 ff2 fp2 : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (lo, bv_unsigned sp + -80); (q + 32, q + 72); (schedb, schedb + SZ_SCH)]%Z ++ fr1_XS H ff1 fp1 ++ fr1_XS H ff2 fp2.

Definition ectx_sh_post (gp tp s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe) (ioc allocb regb v q va schedb cfgb lo shi B : Z) (ra sp s0 s1 s2 s3 s4 s5 s6 : word) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' ff1 fp1 ff2 fp2 j16,
    ms' = MS (mkR (Z_to_bv 64 P_B_ECTX_RET_DSV) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (Z_to_bv 64 ioc) (Z_to_bv 64 (ioc + 8))
                  (Z_to_bv 64 v) (Z_to_bv 64 (v + 32)) (Z_to_bv 64 P_A_DESTROY_ALLOC_SSVC) a3 a4 a5 a6 a7
                  (Z_to_bv 64 (regb + 56)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880))
                  (Z_to_bv 64 (Z.shiftr (regb + 56) 3 + 2147450880)) (Z_to_bv 64 schedb) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_DESTROY_ALLOC_SSVC) fc None m' (seg_rom bsegs)
    /\ munch (ectx_shW lo sp q schedb ff1 fp1 ff2 fp2) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells bsegs m' (bv_unsigned sp + -80) (ectx_frame j16 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' ioc [C8 (wz allocb); C8 (wz regb)] /\ accessible m' ioc 16
    /\ ARegistry LB m' regb ioc v 0
    /\ AStreamSvc LB m' v (mkSVC AVP_SSVC 0 AG_ID_SSVC ioc schedb P_A_DESTROY_ALLOC_SSVC) q
    /\ AImplBlockC LB m' q (mkIMPL (mkSPC AVP_SPCI_IMPL 1 1 1) 0 va [] 1)
    /\ AScheduler LB m' schedb (mkSCH (sched_hdr ioc cfgb) 0 0 1)
    /\ AConfigSvc LB m' cfgb (cfg_hdr ioc)
    /\ AAllocImpl LB m' allocb
    /\ as_RHEAP H s LB m' /\ AXStatics2 m' /\ as_rauxv_ok H m' B
    /\ fresh_frame H LF 1 ff1 fp1 /\ fresh_frame H LF 1 ff2 fp2
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Hypothesis SSHUT : ssvc_shutdown_stmt H.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.

Lemma ectx_sh : forall (gp tp ra sp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (s : as_St H) (LB : list block) (LF : list fframe)
    (ioc allocb regb v q va schedb cfgb sh0 lo shi B : Z) (pv pq pva ps pc pr pa : bptr) (m : mem),
  rw_cells bsegs m ioc [C8 (wz allocb); C8 (wz regb)] -> frobj LF ioc 16 -> ioc mod 8 = 0 -> accessible m ioc 16 ->
  ARegistry LB m regb ioc v 0 ->
  AStreamSvc LB m v (mkSVC AVP_SSVC 0 AG_ID_SSVC ioc schedb P_A_DESTROY_ALLOC_SSVC) q ->
  AImplBlockC LB m q (mkIMPL (mkSPC AVP_SPCI_IMPL 1 1 1) 0 va [] 1) ->
  AScheduler LB m schedb (mkSCH (sched_hdr ioc cfgb) 0 0 sh0) ->
  AConfigSvc LB m cfgb (cfg_hdr ioc) ->
  AAllocImpl LB m allocb ->
  In (pv, v, NEWSZ_SSVC) LB -> In (pq, q, SZ_SPCI_IMPL) LB -> In (pva, va, 8) LB ->
  In (ps, schedb, NEWSZ_SCH) LB -> In (pc, cfgb, NEWSZ_CFG) LB -> In (pr, regb, NEWSZ_REG) LB -> In (pa, allocb, SZ_ALLOCIMPL) LB ->
  pv <> pr ->
  AXStatics2 m -> as_RHEAP H s LB m -> as_rauxv_ok H m B ->
  stk bsegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - AECTX_STACK ->
  mem_inv bsegs m -> tp = Z_to_bv 64 ATP -> bv_unsigned sp mod 16 = 0 ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (ectx_sh_post gp tp s7 s8 s9 s10 s11 F fc s LB LF ioc allocb regb v q va schedb cfgb lo shi B ra sp s0 s1 s2 s3 s4 s5 s6 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 ioc) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
